import { WritableLike } from '..';
import { LineStreamOptions } from './line';
import { QloudStreamOptions } from './qloud';

declare namespace stream {
    export interface DefaultStreamOptions {
        line?: LineStreamOptions;
        qloud?: QloudStreamOptions;
    }
}

/**
 * Returns qloud stream if process.env.QLOUD_LOGGER_STDERR_PARSER is json,
 * otherwise returns line stream
 */
declare function stream(config?: stream.DefaultStreamOptions): WritableLike;

export = stream;
